svg.script:
const svg = document.documentElement;
let mode = 'pimpc', phase = 0, playing = true, device = 'gpu', cores = 4, iteration = 0;
const phaseNames = ['Frozen iterate','Primal updates','Project and copy','Dual updates','Global check'];
const descriptions = [
  ['Frozen iterate', 'Every stage reads the same previous', 'or Nesterov-extrapolated iterate.', 'No new stage update is needed yet.'],
  ['1 · Primal updates', 'Each stage computes Δuₖ and x̄ₖ₊₁', 'from cached local operators and', 'frozen adjacent iterate columns.'],
  ['2 · Project and copy', 'Project zₖ₊₁ onto the joint augmented', 'state-input set X̄; update vₖ.', 'This phase reads new primal results.'],
  ['3 · Dual updates', 'θ, β and λ accumulate violations', 'of state copy, input effect and', 'split dynamics, stage by stage.'],
  ['4 · Global check', 'Reduce the horizon residuals.', 'Stop if converged; otherwise use', 'Nesterov extrapolation or restart.']
];
function keyActivate(event, action) { if (event.key === 'Enter' || event.key === ' ') { event.preventDefault(); if (action === 'play') togglePlay(); else if (action === 'equations') toggleEquations(); else if (action === 'cpu' || action === 'gpu') setDevice(action); else if (action.startsWith('cores')) setCores(Number(action.slice(5))); else setMode(action); } }
function setMode(value) { mode = value; phase = 0; const standard = value === 'standard'; document.getElementById('phase-slider').max = standard ? 3 : 4; document.getElementById('pimpc-view').classList.toggle('hidden', standard); document.getElementById('standard-view').classList.toggle('hidden', !standard); document.getElementById('global-phase').classList.toggle('hidden', standard); document.getElementById('explanation-panel').classList.toggle('hidden', standard); document.getElementById('standard-side').classList.toggle('hidden', !standard); document.getElementById('residual-panel').classList.toggle('hidden', standard); document.getElementById('cpu-button').classList.toggle('hidden', standard); document.getElementById('gpu-button').classList.toggle('hidden', standard); document.getElementById('core-controls').classList.toggle('hidden', standard || device !== 'cpu'); document.getElementById('pimpc-button').classList.toggle('on', !standard); document.getElementById('standard-button').classList.toggle('on', standard); render(); }
function setDevice(value) { device = value; document.getElementById('gpu-layout').classList.toggle('hidden', value !== 'gpu'); document.getElementById('cpu-layout').classList.toggle('hidden', value !== 'cpu'); document.getElementById('core-controls').classList.toggle('hidden', value !== 'cpu' || mode !== 'pimpc'); document.getElementById('gpu-button').classList.toggle('on', value === 'gpu'); document.getElementById('cpu-button').classList.toggle('on', value === 'cpu'); document.getElementById('device-heading').textContent = value === 'gpu' ? 'GPU WORK ALLOCATION' : 'CPU WORK ALLOCATION'; document.getElementById('device-line-1').textContent = value === 'gpu' ? 'A kernel processes many stage columns.' : 'Available cores process stage columns.'; document.getElementById('device-line-2').textContent = value === 'gpu' ? 'Tiles show possible concurrent work.' : 'Extra stages wait for the next batch.'; }
function setCores(value) { cores = value; document.querySelectorAll('[data-cores]').forEach(node => node.classList.toggle('on', Number(node.getAttribute('data-cores')) === value)); document.getElementById('cpu-schedule-label').textContent = `Illustrative ${value}-core schedule${value === 8 ? ' · first four shown' : ''}`; const labels = document.querySelectorAll('#cpu-layout .res-label'); labels.forEach((node, index) => { node.textContent = index < value ? `core ${index + 1} · k${index}` : `queued · k${index}`; }); }
function setPhase(value) { phase = value; render(); }
function setIteration(value) { iteration = value; document.getElementById('iteration-slider').value = value; document.getElementById('iteration-value').textContent = `${value} / 25`; const bases = [340, 330, 350], rates = [0.145, 0.12, 0.105], ids = ['res-state','res-input','res-dynamics']; ids.forEach((id, index) => document.getElementById(id).setAttribute('width', Math.max(7, Math.round(bases[index] * Math.exp(-rates[index] * value))))); }
function togglePlay() { playing = !playing; document.getElementById('play-label').textContent = playing ? 'Pause' : 'Play'; document.getElementById('play-button').setAttribute('aria-label', playing ? 'Pause animation' : 'Play animation'); }
function toggleEquations() { const open = document.getElementById('equations').classList.toggle('open'); document.getElementById('equations-label').textContent = open ? 'Hide equations' : 'Show equations'; document.getElementById('equations-button').setAttribute('aria-label', open ? 'Hide equations' : 'Show equations'); }
function render() { document.getElementById('phase-slider').value = phase; document.getElementById('phase-value').textContent = `${phase + 1} / ${mode === 'pimpc' ? 5 : 4}`; svg.setAttribute('aria-label', `${mode === 'pimpc' ? 'πMPC: ' + phaseNames[phase] : 'Riccati ADMM: backward sweep step ' + (phase + 1)}`); document.querySelectorAll('[data-phase]').forEach(node => { const step = Number(node.getAttribute('data-phase')); node.classList.toggle('active', step === phase); node.classList.toggle('done', step < phase); node.classList.toggle('dim', step > phase); }); document.querySelectorAll('#riccati-chain rect').forEach((node, index) => node.classList.toggle('standard-active', index === phase)); const lines = descriptions[phase]; ['phase-heading','phase-line-1','phase-line-2','phase-line-3'].forEach((id, index) => document.getElementById(id).textContent = lines[index]); document.querySelectorAll('#gpu-layout .tile').forEach((node, index) => node.classList.toggle('on', index % 5 === phase || phase === 4)); }
if (window.matchMedia && window.matchMedia('(prefers-reduced-motion: reduce)').matches) { playing = false; document.getElementById('play-label').textContent = 'Play'; document.getElementById('play-button').setAttribute('aria-label','Play animation'); }
setInterval(() => { if (playing && !document.getElementById('equations').classList.contains('open')) { const next = (phase + 1) % (mode === 'pimpc' ? 5 : 4); if (next === 0 && mode === 'pimpc') setIteration((iteration + 1) % 26); setPhase(next); } }, 1700);
setDevice('gpu'); setCores(4); setIteration(0);
render();
